class _BoostSample{final double target,actual;final int rpm;final int? load;final double? throttle;final bool loaded;_BoostSample(this.target,this.actual,this.rpm,this.load,this.throttle,this.loaded);}
class _BoostPainter extends CustomPainter {
  _BoostPainter({required this.samples, this.targetNow, this.actualNow});
  final List<_BoostSample> samples;
  final double? targetNow, actualNow;
  @override
  void paint(Canvas c, Size s) {
    final List<_BoostSample> list = samples.isEmpty && targetNow != null && actualNow != null
        ? <_BoostSample>[_BoostSample(targetNow!, actualNow!, 0, null, null, false)]
        : samples;
    if (list.isEmpty) return;
    final List<double> vals = list.expand<double>((e) => <double>[e.target, e.actual]).toList();
    final double minV = math.max(0.0, vals.reduce((a,b)=>math.min(a,b).toDouble()) - .15).toDouble();
    double maxV = (vals.reduce((a,b)=>math.max(a,b).toDouble()) + .15).toDouble();
    if ((maxV-minV).abs() < .001) maxV=minV+.30;
    Offset point(int i,double v)=>Offset(list.length==1?s.width/2:i*s.width/(list.length-1),s.height-(((v-minV)/(maxV-minV)).clamp(0.0,1.0)*s.height));
    final a=Paint()..color=Colors.white..strokeWidth=2..style=PaintingStyle.stroke;
    final b=Paint()..color=AppColors.accentBright..strokeWidth=2..style=PaintingStyle.stroke;
    final pa=Path(),pb=Path();
    for(var i=0;i<list.length;i++){final x=point(i,list[i].target),y=point(i,list[i].actual);if(i==0){pa.moveTo(x.dx,x.dy);pb.moveTo(y.dx,y.dy);}else{pa.lineTo(x.dx,x.dy);pb.lineTo(y.dx,y.dy);}}
    c.drawPath(pa,a);c.drawPath(pb,b);
  }
  @override bool shouldRepaint(covariant _BoostPainter old)=>true;
}

